   546 #ifndef FLATBUFFERS_PREFER_PRINTF
   547 // Wraps a string to a maximum length, inserting new lines where necessary. Any
   548 // existing whitespace will be collapsed down to a single space. A prefix or
   549 // suffix can be provided, which will be inserted before or after a wrapped
   550 // line, respectively.
   551 inline std::string WordWrap(const std::string in, size_t max_length,
   552                             const std::string wrapped_line_prefix,
   553                             const std::string wrapped_line_suffix) {
   554   std::istringstream in_stream(in);
   555   std::string wrapped, line, word;
   556
   557   in_stream >> word;
   558   line = word;
   559
   560   while (in_stream >> word) {
   561     if ((line.length() + 1 + word.length() + wrapped_line_suffix.length()) <
   562         max_length) {
   563       line += " " + word;
   564     } else {
   565       wrapped += line + wrapped_line_suffix + "\n";
   566       line = wrapped_line_prefix + word;
   567     }
   568   }
   569   wrapped += line;
   570
   571   return wrapped;
   572 }
