   498 // Converts whatever prefix of the incoming string corresponds to a valid
   499 // UTF-8 sequence into a unicode code. The incoming pointer will have been
   500 // advanced past all bytes parsed.
   501 // returns -1 upon corrupt UTF-8 encoding (ignore the incoming pointer in
   502 // this case).
   503 inline int FromUTF8(const char **in) {
   504   int len = 0;
   505   // Count leading 1 bits.
   506   for (int mask = 0x80; mask >= 0x04; mask >>= 1) {
   507     if (**in & mask) {
   508       len++;
   509     } else {
   510       break;
   511     }
   512   }
   513   if ((static_cast<unsigned char>(**in) << len) & 0x80)
   514     return -1;  // Bit after leading 1's must be 0.
   515   if (!len) return *(*in)++;
   516   // UTF-8 encoded values with a length are between 2 and 4 bytes.
   517   if (len < 2 || len > 4) { return -1; }
   518   // Grab initial bits of the code.
   519   int ucc = *(*in)++ & ((1 << (7 - len)) - 1);
   520   for (int i = 0; i < len - 1; i++) {
   521     if ((**in & 0xC0) != 0x80) return -1;  // Upper bits must 1 0.
   522     ucc <<= 6;
   523     ucc |= *(*in)++ & 0x3F;  // Grab 6 more bits of the code.
   524   }
   525   // UTF-8 cannot encode values between 0xD800 and 0xDFFF (reserved for
   526   // UTF-16 surrogate pairs).
   527   if (ucc >= 0xD800 && ucc <= 0xDFFF) { return -1; }
   528   // UTF-8 must represent code points in their shortest possible encoding.
   529   switch (len) {
   530     case 2:
   531       // Two bytes of UTF-8 can represent code points from U+0080 to U+07FF.
   532       if (ucc < 0x0080 || ucc > 0x07FF) { return -1; }
   533       break;
   534     case 3:
   535       // Three bytes of UTF-8 can represent code points from U+0800 to U+FFFF.
   536       if (ucc < 0x0800 || ucc > 0xFFFF) { return -1; }
   537       break;
   538     case 4:
   539       // Four bytes of UTF-8 can represent code points from U+10000 to U+10FFFF.
   540       if (ucc < 0x10000 || ucc > 0x10FFFF) { return -1; }
   541       break;
   542   }
   543   return ucc;
   544 }
